<script setup lang="ts">
import { onBeforeUnmount,onMounted,ref } from 'vue';
import { api } from '../api';
import type { Asset } from '../types';
import type { FlowDetail } from '../../shared/flows';
const props=defineProps<{detail:FlowDetail}>();const emit=defineEmits<{saved:[detail:FlowDetail]}>();
const selected=ref<Asset[]>([]),candidates=ref<Asset[]>([]),search=ref(''),page=ref(1),total=ref(0),loading=ref(false),busy=ref(false),error=ref('');let sequence=0;
async function load(){const seq=++sequence;loading.value=true;error.value='';try{const r=await api.listAssets({status:'空闲',category:props.detail.requisition!.category_path,search:search.value,page:page.value,pageSize:10});if(seq===sequence){candidates.value=r.items;total.value=r.total}}catch(e){if(seq===sequence)error.value=e instanceof Error?e.message:'读取库存失败'}finally{if(seq===sequence)loading.value=false}}
async function save(){busy.value=true;error.value='';try{emit('saved',await api.allocateRequisition(props.detail.flow.id,selected.value.map(a=>a.asset_code),props.detail.requisition!.version))}catch(e){error.value=e instanceof Error?e.message:'分配失败，请重试'}finally{busy.value=false}}
onMounted(()=>{void load()});onBeforeUnmount(()=>{sequence++});
</script>
<template><section class="allocation-panel"><h3>分配设备 <small>需 {{detail.requisition?.quantity}} 件，已选 {{selected.length}} 件</small></h3><p class="label-help">选择与申请类别一致的空闲设备。{{detail.flow.status==='approved'?'分配后将按已批准的申请更新本人名下资产。':'分配后保留设备，审批通过才更新资产归属。'}}</p><p v-if="error" role="alert" class="scan-error">{{error}}</p><div v-for="asset in selected" :key="asset.id" class="flow-candidate"><span><strong>{{asset.asset_code}} · {{asset.name}}</strong></span><button type="button" class="text-button" :disabled="busy" @click="selected=selected.filter(a=>a.id!==asset.id)">移除</button></div><form class="flow-picker-search" @submit.prevent="page=1;load()"><label class="field"><span>搜索空闲设备</span><input v-model="search" :disabled="busy" placeholder="资产编码、名称或型号"/></label><button class="secondary-button" :disabled="loading||busy">搜索</button></form><p v-if="loading" role="status">正在读取库存…</p><p v-else-if="!candidates.length" class="muted">没有符合分类的空闲设备，可调整搜索或先采购入库。</p><div v-for="asset in candidates" :key="asset.id" class="flow-candidate"><span><strong>{{asset.asset_code}} · {{asset.name}}</strong><small>{{asset.model||'未填型号'}} · {{asset.location||'未填位置'}}</small></span><button type="button" class="secondary-button" :disabled="busy||selected.some(a=>a.id===asset.id)||selected.length>=detail.requisition!.quantity||!!asset.assignee_employee_id||!!asset.assignee" @click="selected.push(asset)">{{selected.some(a=>a.id===asset.id)?'已选择':'选择'}}</button></div><div class="pager"><span>共 {{total}} 件</span><div><button type="button" :disabled="busy||loading||page<=1" @click="page--;load()">上一页</button><span>{{page}}</span><button type="button" :disabled="busy||loading||page*10>=total" @click="page++;load()">下一页</button></div></div><button type="button" class="primary-button" :disabled="busy||selected.length!==detail.requisition?.quantity" @click="save">{{busy?'正在分配…':detail.flow.status==='approved'?'确认分配并入账':'保存设备分配'}}</button></section></template>
